const fs=require('node:fs'),path=require('node:path');
async function main(){
 const pages=(await(await fetch('http://127.0.0.1:57218/json/list')).json()).filter(t=>t.type==='page'&&t.url.includes('/apps/pc-app/dist/ui/index.html'));
 if(pages.length!==1)throw Error('Unique original CloudA renderer required');
 const expression=`(()=>{if(!/^#\\/(battle|companions)/.test(location.hash))throw Error('Only approved roster/battle public UI');const rect=e=>{const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};return{route:location.hash,visibleText:document.body.innerText.slice(0,16000),headings:[...document.querySelectorAll('h1,h2,h3')].map(e=>e.innerText),alerts:[...document.querySelectorAll('[role=alert]')].map(e=>e.innerText),status:[...document.querySelectorAll('[role=status]')].map(e=>e.innerText),buttons:[...document.querySelectorAll('button')].filter(e=>{const r=e.getBoundingClientRect();return r.width&&r.height}).map(e=>({text:e.innerText,label:e.getAttribute('aria-label'),disabled:e.disabled,rect:rect(e)})),dataNodes:[...document.querySelectorAll('[data-pet-id],[data-report-id],[data-session-id]')].map(e=>({petId:e.getAttribute('data-pet-id'),reportId:e.getAttribute('data-report-id'),sessionId:e.getAttribute('data-session-id'),text:e.innerText.slice(0,1200)}))}})()`;
 const ws=new WebSocket(pages[0].webSocketDebuggerUrl);
 const result=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>{ws.close();reject(Error('Readonly timeout'));},10000);ws.onopen=()=>ws.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{returnByValue:true,expression}}));ws.onerror=()=>{clearTimeout(timer);reject(Error('Readonly connection failed'));};ws.onmessage=e=>{const r=JSON.parse(e.data);if(r.id!==1)return;clearTimeout(timer);ws.close();if(r.error||r.result?.exceptionDetails)reject(Error('Readonly public UI projection failed'));else resolve(r.result.result.value);};});
 const report={at:new Date().toISOString(),method:'Readonly public DOM on approved roster/report routes only; no hidden business API/input/mutation/credential values',result};
 const output=path.join(__dirname,'cloudA-battle-public-ui-'+process.argv[2]+'-20261026.json');fs.writeFileSync(output,JSON.stringify(report,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({output,...report}));
}main().catch(e=>{console.error(e.message);process.exitCode=1;});
